'use strict';
(() => {
const DATA=JSON.parse(document.getElementById('course-data').textContent);
const QUESTIONS=new Map(DATA.questions.map(q=>[q.id,q]));
const LESSONS=new Map(DATA.lessons.map(l=>[l.id,l]));
const EXERCISES=new Map(DATA.lessons.flatMap(l=>l.exercises.map(e=>[e.id,{...e,lesson:l.id}])));
const DEFLIST=DATA.lessons.flatMap(l=>l.definitions||[]);
const DEFINITIONS=new Map(DEFLIST.map(d=>[d.id,d]));
const STORE='arslan-learning-studio-v1';
const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const n2=n=>String(n).padStart(2,'0');
const levelName=n=>['','Basic','Medium','Advanced'][n]||'Guided';
const localDay=(d=new Date())=>`${d.getFullYear()}-${n2(d.getMonth()+1)}-${n2(d.getDate())}`;
const icon=(name,size=18)=>{const p={grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',book:'<path d="M3 4h6a4 4 0 0 1 3 1.5A4 4 0 0 1 15 4h6v16h-6a4 4 0 0 0-3 1 4 4 0 0 0-3-1H3z"/><path d="M12 5.5V21"/>',play:'<path d="m9 5 11 7-11 7z"/>',check:'<path d="m5 12 4 4L19 6"/>',arrow:'<path d="M4 12h15m-6-6 6 6-6 6"/>',back:'<path d="M20 12H5m6-6-6 6 6 6"/>',chevron:'<path d="m9 5 7 7-7 7"/>',refresh:'<path d="M20 8a9 9 0 1 0 0 8M20 3v5h-5"/>',bookmark:'<path d="M6 3h12v18l-6-4-6 4z"/>',chat:'<path d="M21 11.5a8.5 8.5 0 0 1-8.5 8.5H4l-2 2V11.5A9.5 9.5 0 0 1 11.5 2 9.5 9.5 0 0 1 21 11.5z"/><path d="M7 9h9m-9 4h6"/>',spark:'<path d="m12 3 2.7 6.3L21 12l-6.3 2.7L12 21l-2.7-6.3L3 12l6.3-2.7z"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',settings:'<path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="3" fill="currentColor" stroke="none"/><circle cx="16" cy="17" r="3" fill="currentColor" stroke="none"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',upload:'<path d="M12 16V4m-5 5 5-5 5 5M4 16v5h16v-5"/>',list:'<path d="M9 5h12M9 12h12M9 19h12M3 5h1M3 12h1M3 19h1"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 11h18m-13 5h3"/>',target:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',skip:'<path d="m5 5 10 7L5 19zM19 5v14"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',bulb:'<path d="M9 18h6m-6 3h6M8.5 15a6 6 0 1 1 7 0V18h-7z"/>',flag:'<path d="M5 21V3h13l-3 4 3 4H5"/>',shield:'<path d="m12 2 9 4v6c0 5-9 10-9 10S3 17 3 12V6z"/><path d="m8 12 3 3 5-6"/>',note:'<path d="M5 3h10l4 4v14H5zM14 3v5h5M8 12h8m-8 4h6"/>',copy:'<rect x="8" y="8" width="12" height="13" rx="2"/><path d="M16 8V3H3v13h5"/>',external:'<path d="M14 3h7v7m0-7-11 11M10 3H3v18h18v-7"/>',layers:'<path d="m12 3 10 5-10 5L2 8zm-10 9 10 5 10-5M2 16l10 5 10-5"/>',alert:'<path d="m12 3 10 18H2zM12 9v5m0 3v1"/>',bolt:'<path d="m13 2-9 12h7l-1 8 10-13h-7z"/>',trash:'<path d="M3 6h18M9 6V3h6v3M6 6l1 15h10l1-15M10 10v7m4-7v7"/>'};return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${p[name]||p.book}</svg>`;};
const defaultState=()=>({schemaVersion:1,answers:{},skipped:[],skippedTopics:[],bookmarks:[],cards:{},notes:{},threads:{},exercises:{},coverage:[],reading:{},definitionReading:{},definitionStatus:{},events:[],settings:{goal:10,tutorMode:'offline',aiConsent:false},lastLesson:1,session:null});
let saveOK=true;
function validateState(v){
 if(!v||typeof v!=='object'||v.schemaVersion!==1)throw Error('This is not a compatible Learning Studio progress file.');
 const s=defaultState(), isQ=x=>typeof x==='string'&&QUESTIONS.has(x),isL=x=>Number.isInteger(x)&&LESSONS.has(x);
 for(const k of ['skipped','bookmarks'])s[k]=[...new Set((Array.isArray(v[k])?v[k]:[]).filter(isQ))];
 s.skippedTopics=[...new Set((v.skippedTopics||[]).filter(isL))];
 s.coverage=[...new Set((v.coverage||[]).filter(x=>Number.isInteger(x)&&x>0&&x<=DATA.coverage.length))];
 for(const [id,a] of Object.entries(v.answers||{})){if(!isQ(id)||!a||!Number.isInteger(a.chosen)||a.chosen<0||a.chosen>3)continue;const q=QUESTIONS.get(id);s.answers[id]={chosen:a.chosen,correct:a.chosen===q.answer,firstCorrect:!!a.firstCorrect,attempts:Math.max(1,Math.min(100000,Number(a.attempts)||1)),at:String(a.at||'').slice(0,40),assisted:!!a.assisted};}
 for(const [id,c] of Object.entries(v.cards||{}))if(isQ(id)&&c&&['again','known'].includes(c.rating))s.cards[id]={rating:c.rating,at:String(c.at||'').slice(0,40)};
 const goodKey=k=>/^q:L\d{2}Q\d{2}$/.test(k)&&isQ(k.slice(2))||/^e:E\d{2}\.\d$/.test(k)&&EXERCISES.has(k.slice(2))||/^l:\d+$/.test(k)&&isL(Number(k.slice(2)))||/^d:D\d{2}-\d{3}$/.test(k)&&DEFINITIONS.has(k.slice(2));
 for(const [id,text] of Object.entries(v.notes||{}))if(goodKey(id)&&typeof text==='string')s.notes[id]=text.slice(0,12000);
 for(const [id,msgs] of Object.entries(v.threads||{}))if(goodKey(id)&&Array.isArray(msgs))s.threads[id]=msgs.slice(-40).filter(m=>m&&['user','assistant'].includes(m.role)&&typeof m.text==='string').map(m=>({role:m.role,text:m.text.slice(0,12000),label:String(m.label||'Saved discussion').slice(0,80),at:String(m.at||'').slice(0,40),sources:(Array.isArray(m.sources)?m.sources:[]).filter(x=>x&&isL(x.lesson)).map(x=>({lesson:x.lesson,page:Math.max(1,Math.min(96,Number(x.page)||1))})).slice(0,4)}));
 for(const [id,e] of Object.entries(v.exercises||{}))if(EXERCISES.has(id)&&e)s.exercises[id]={text:String(e.text||'').slice(0,12000),revealed:!!e.revealed,rating:['again','known'].includes(e.rating)?e.rating:null};
 for(const [id,n] of Object.entries(v.reading||{}))if(isL(Number(id)))s.reading[id]=Math.max(0,Math.min(LESSONS.get(Number(id)).reading.length-1,Number(n)||0));
 for(const [id,n] of Object.entries(v.definitionReading||{}))if(isL(Number(id)))s.definitionReading[id]=Math.max(0,Math.min(LESSONS.get(Number(id)).definitions.length-1,Math.floor(Number(n)||0)));
 for(const [id,r] of Object.entries(v.definitionStatus||{}))if(DEFINITIONS.has(id)&&r&&['known','again','skipped'].includes(r.rating))s.definitionStatus[id]={rating:r.rating,at:String(r.at||'').slice(0,40)};
 s.events=(Array.isArray(v.events)?v.events:[]).filter(e=>e&&isQ(e.id)&&/^\d{4}-\d{2}-\d{2}$/.test(e.day)).slice(-10000).map(e=>({id:e.id,day:e.day,correct:!!e.correct}));
 s.settings.goal=Math.max(1,Math.min(100,Number(v.settings?.goal)||10));
 s.settings.aiConsent=!!v.settings?.aiConsent;
 s.settings.tutorMode=v.settings?.tutorMode==='ai'?'ai':'offline';
 s.lastLesson=isL(v.lastLesson)?v.lastLesson:1;
 if(v.session&&Array.isArray(v.session.ids)){const ids=v.session.ids.filter(isQ);if(ids.length){const results={};for(const [id,r] of Object.entries(v.session.results||{}))if(ids.includes(id)&&Number.isInteger(r.chosen)&&r.chosen>=0&&r.chosen<4)results[id]={chosen:r.chosen,correct:r.chosen===QUESTIONS.get(id).answer};s.session={ids,index:Math.max(0,Math.min(ids.length,Number(v.session.index)||0)),results,mode:['guided','1','2','3','review'].includes(v.session.mode)?v.session.mode:'guided',selected:Number.isInteger(v.session.selected)&&v.session.selected>=0&&v.session.selected<4?v.session.selected:null,help:Object.fromEntries(Object.entries(v.session.help||{}).filter(([id,val])=>ids.includes(id)&&val===true)),lesson:isL(v.session.lesson)?v.session.lesson:s.lastLesson};}}
 return s;
}
let state;
try{const raw=localStorage.getItem(STORE);state=raw?validateState(JSON.parse(raw)):defaultState();localStorage.setItem(STORE,JSON.stringify(state));}catch(e){state=defaultState();saveOK=false;}
let view='dashboard',activeLesson=state.lastLesson,reviewTab='mistakes',lessonSearch='',lessonGroup='all',coverageSearch='',flashIndex=0,flashBack=false,activeExercise=null;
let glossarySearch='',glossaryLesson='all',glossaryStatus='all',glossaryPageIndex=0,termIndex=0,termBack=false,lessonMode='single';
let backend={available:false,token:null,model:null},toastTimer=null,pdfURL=null,lastFocus=null;
const busy=new Set();
function save(){try{localStorage.setItem(STORE,JSON.stringify(state));saveOK=true;}catch(e){saveOK=false;}$('#storageWarning').classList.toggle('hidden',saveOK);}
function toast(text){$('#toast').textContent=text;$('#toast').classList.remove('hidden');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.add('hidden'),4200);}
function questionNow(){const s=state.session;return s&&s.index<s.ids.length?QUESTIONS.get(s.ids[s.index]):null;}
function context(){
 if(['lesson','termcards'].includes(view)){const d=definitionNow();if(d)return {key:'d:'+d.id,lesson:d.lesson,definition:d,title:d.term};}
 if(view==='quiz'&&questionNow()){const q=questionNow();return {key:'q:'+q.id,lesson:q.lesson,question:q,title:q.concept};}
 if(view==='flashcards'){const l=LESSONS.get(activeLesson),q=QUESTIONS.get(l.questionIds[flashIndex%l.questionIds.length]);return {key:'q:'+q.id,lesson:q.lesson,question:q,title:q.concept};}
 if(view==='exercises'){const l=LESSONS.get(activeLesson),e=EXERCISES.get(activeExercise)||EXERCISES.get(l.exercises[0].id);return {key:'e:'+e.id,lesson:e.lesson,exercise:e,title:e.id+' workbook exercise'};}
 const l=LESSONS.get(activeLesson)||LESSONS.get(1);return {key:'l:'+l.id,lesson:l.id,title:l.title};
}
function stats(){const aa=Object.values(state.answers), first=aa.filter(a=>a.firstCorrect).length;return {answered:aa.length,correct:aa.filter(a=>a.correct).length,first:first,accuracy:aa.length?Math.round(100*first/aa.length):null,mistakes:aa.filter(a=>!a.correct).length,today:state.events.filter(e=>e.day===localDay()).length};}
function lessonStats(id){const qs=LESSONS.get(id).questionIds;return {done:qs.filter(q=>state.answers[q]).length,correct:qs.filter(q=>state.answers[q]?.correct).length};}
function pageRef(l){return `pp. ${l.page}-${l.endPage}`;}
function labelLevel(level){return `<span class="pill ${level===1?'green':level===2?'accent':'amber'}">${levelName(level)}</span>`;}
function renderNav(){const s=stats(),pct=Math.round(s.answered/228*100);const items=[['dashboard','grid','Overview'],['quiz','play','Practice room'],['lessons','book','All lessons'],['glossary','list','Definitions & examples'],['review','refresh','Review queue'],['coverage','list','CV coverage'],['plan','calendar','3-day route'],['notes','note','My notes']];$('#sidebar').innerHTML=`<div class="brand"><div class="brandmark">${icon('layers',23)}</div><div><div class="brandname">Learning Studio</div><div class="brandsub">YOUR CV. ONE CONCEPT AT A TIME.</div></div></div><div class="navlabel">YOUR WORKSPACE</div><nav>${items.map(([key,ic,title])=>`<button class="navbtn ${(view===key||(key==='lessons'&&['lesson','flashcards','termcards','exercises'].includes(view)))?'active':''}" data-action="nav" data-view="${key}" ${view===key?'aria-current="page"':''}>${icon(ic)}${title}${key==='review'&&s.mistakes?`<span class="navcount">${s.mistakes}</span>`:''}</button>`).join('')}</nav><div class="navlabel">TOOLS</div><button class="navbtn ${view==='settings'?'active':''}" data-action="nav" data-view="settings">${icon('settings')}Setup & backups</button><button class="navbtn" data-action="pdf" data-page="1">${icon('external')}Original workbook</button><div class="sidebottom"><div class="sideprogress"><div class="row between"><strong>Your learning path</strong><span class="small muted">${pct}%</span></div><div class="progressbar"><span style="width:${pct}%"></span></div><div class="small muted">${s.answered} / 228 questions attempted</div></div><div class="profile"><div class="avatar">MA</div><div><strong>Muhammad Arslan</strong><p>Private, local learning space</p></div></div></div>`;
 const names={dashboard:'Overview',quiz:'Practice room',lessons:'All lessons',lesson:'One term at a time',glossary:'Definitions & examples',termcards:'Definition recall',review:'Review queue',coverage:'CV coverage',plan:'Three-day route',settings:'Setup & backups',notes:'My notes',flashcards:'Recall cards',exercises:'Workbook exercises'};
 $('#topbar').innerHTML=`<div class="row"><button class="iconbtn mobilemenu" data-action="toggle-menu" aria-label="Open navigation">${icon('menu')}</button><div class="breadcrumb">Your workspace ${icon('chevron',12)} <b>${names[view]}</b></div></div><div class="row"><span class="modebadge"><span class="dot"></span>${backend.available&&state.settings.tutorMode==='ai'?'Live tutor connected':'Offline-ready'} <span class="hide-small">&middot; ${saveOK?'Progress saved locally':'Session only'}</span></span><button class="iconbtn" data-action="help" aria-label="How this portal works">${icon('bulb',17)}</button></div>`;
}
function render(scroll=false){renderNav();const renderers={dashboard:dashboard,lessons:lessonsPage,lesson:lessonPage,quiz:quizPage,review:reviewPage,coverage:coveragePage,plan:planPage,settings:settingsPage,notes:notesPage,flashcards:flashcardsPage,exercises:exercisesPage,glossary:glossaryPage,termcards:termcardsPage};$('#main').innerHTML=(renderers[view]||dashboard)();if($('#tutorHost'))renderTutor();$('#storageWarning').classList.toggle('hidden',saveOK);if(scroll)window.scrollTo(0,0);}
function navigate(v){if(v==='quiz'){resumePractice();return;}view=v;$('#sidebar').classList.remove('open');$('#menuOverlay').classList.remove('visible');render(true);}
function nextLessonId(start=1){for(let step=0;step<38;step++){const id=((start-1+step)%38)+1;if(!state.skippedTopics.includes(id)&&LESSONS.get(id).questionIds.some(q=>!state.answers[q]&&!state.skipped.includes(q)))return id;}return null;}
function dashboard(){const s=stats(),next=nextLessonId(state.lastLesson)||state.lastLesson,l=LESSONS.get(next),pct=Math.round(s.answered/228*100);const radius=66,circ=2*Math.PI*radius;const upcoming=DATA.lessons.filter(x=>x.id>=next&&!state.skippedTopics.includes(x.id)).slice(0,3);const days=Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()-(6-i));return {name:d.toLocaleDateString('en-US',{weekday:'short'}).slice(0,1),day:localDay(d),n:state.events.filter(e=>e.day===localDay(d)).length};});const max=Math.max(1,...days.map(d=>d.n));return `<div class="pageheading row between wrap"><div><div class="eyebrow">A calmer way to prepare</div><h1>Welcome back, Arslan.</h1><p>No more reading marathons. Learn one idea, try it, then talk it through.</p></div><span class="pill">${icon('book',13)}38 lessons &middot; Your workbook</span></div><section class="hero"><div><div class="eyebrow">${s.answered?'CONTINUE YOUR JOURNEY':'YOUR FIRST SMALL STEP'}</div><h2>${s.answered?esc(l.title):'Build understanding.<br>Then build confidence.'}</h2><p>${s.answered?`Pick up with Lesson ${n2(next)}. Go at your own pace; every level and topic stays open.`:'Start with basic definitions, move into examples, then defend the choices. Ask for help whenever something does not click.'}</p><div class="row wrap"><button class="btn primary" data-action="resume">${icon('play',16)}${s.answered?'Continue learning':'Start with the basics'}</button><button class="btn ghost" data-action="lesson" data-id="${next}">Teach me first ${icon('arrow',15)}</button></div></div><div class="heroring"><svg width="166" height="166" viewBox="0 0 166 166" aria-label="${pct}% of questions attempted"><circle cx="83" cy="83" r="${radius}" fill="none" stroke="#dfe3f2" stroke-width="8"/><circle cx="83" cy="83" r="${radius}" fill="none" stroke="#6873dc" stroke-width="8" stroke-linecap="round" stroke-dasharray="${circ}" stroke-dashoffset="${circ*(1-pct/100)}" transform="rotate(-90 83 83)"/></svg><div class="ringcenter"><strong>${pct}%</strong><span>of your quiz path<br>attempted</span></div></div></section><div class="definition-update-banner"><div><b>${DEFLIST.length} clear definitions, with examples.</b><span>Separate entries, lesson-by-lesson recall, and quick lookup. No bundled definition paragraphs.</span></div><button class="btn sm" data-action="nav" data-view="glossary">Explore definitions ${icon('arrow',14)}</button></div><div class="metricgrid">${metric('check','Questions attempted',s.answered,'Out of 228 guided questions')}${metric('target','First-try accuracy',s.accuracy===null?'--':s.accuracy+'%','Study help is available before answering')}${metric('refresh','Ready for review',s.mistakes,'Questions last answered incorrectly')}${metric('bolt','Today\'s practice',`${s.today}<span style="font-size:14px;color:var(--muted)"> / ${state.settings.goal}</span>`,'Attempts, including repeat practice')}</div><div class="dashboardlower"><section class="card"><div class="sectionhead"><div><h2>Your learning path</h2><p>Follow the book, or jump to any topic.</p></div><button class="textbtn" data-action="nav" data-view="lessons">All 38 lessons ${icon('arrow',13)}</button></div>${upcoming.map(x=>`<div class="pathitem"><span class="lessonnum">${n2(x.id)}</span><div class="pathcopy"><strong>${esc(x.title)}</strong><span>${pageRef(x)} &middot; ${lessonStats(x.id).done}/6 answered &middot; 3 exercises</span></div><button class="iconbtn" data-action="start" data-id="${x.id}" aria-label="Practice lesson ${x.id}">${icon('arrow',16)}</button></div>`).join('')}<div class="notice accent" style="margin-top:20px">${icon('bulb',15)} Stuck on a word? Open the tutor beside your question. No need to leave your place.</div></section><section class="card"><div class="sectionhead"><div><h2>Small steps, every day</h2><p>Your actual practice activity</p></div>${icon('calendar',18)}</div><div class="chartbars">${days.map((d,i)=>`<div class="barcol" title="${esc(d.day)}: ${d.n} attempts"><span>${d.n||''}</span><div class="bar ${i===6?'today':''}" style="height:${Math.max(3,43*d.n/max)}px"></div><span>${d.name}</span></div>`).join('')}</div><div class="divider"></div><div class="daysteps"><div class="daystep"><b>01</b><div><strong>Understand the definition</strong><p>Make the basic pieces feel familiar.</p></div></div><div class="daystep"><b>02</b><div><strong>Apply it to a small example</strong><p>Trace what happens, step by step.</p></div></div><div class="daystep"><b>03</b><div><strong>Defend the decision</strong><p>Explain why, why not, and the trade-off.</p></div></div></section></div><p class="footersource">Built from your 96-page foundations workbook. Original order, 114 original exercises and a 153-item CV map. Scores track practice, not proof of production expertise.</p>`;}
function metric(ic,label,value,foot){return `<div class="metric"><div class="metriclabel">${icon(ic,15)}${label}</div><div class="metricvalue">${value}</div><div class="metricfoot">${foot}</div></div>`;}
function lessonsPage(){const query=lessonSearch.toLowerCase().trim();const matched=DATA.lessons.filter(l=>(lessonGroup==='all'||l.group===Number(lessonGroup))&&(!query||(l.title+' '+l.cv+' '+l.source.map(s=>s.text).join(' ')).toLowerCase().includes(query)));return `<div class="pageheading"><div class="eyebrow">The entire workbook, unlocked</div><h1>Choose your next idea.</h1><p>All 38 lessons are available. Skip, revisit or jump ahead whenever you need.</p></div><div class="lessonfilters"><label class="searchbox">${icon('search',17)}<input id="lessonSearch" aria-label="Search lessons and workbook text" placeholder="Search a topic, tool or skill..." value="${esc(lessonSearch)}"></label><select id="lessonGroup" class="field" aria-label="Filter lesson group"><option value="all">All topic groups</option>${DATA.groups.map(g=>`<option value="${g.id}" ${String(g.id)===lessonGroup?'selected':''}>${esc(g.title)}</option>`).join('')}</select></div><div id="lessonResults">${matched.length?DATA.groups.map(g=>{const ls=matched.filter(l=>l.group===g.id);return ls.length?`<div class="grouphead"><span class="number">${n2(g.id)}</span><h2>${esc(g.title)}</h2><span>${ls.length} lessons</span></div><div class="topicgrid">${ls.map(topicCard).join('')}</div>`:'';}).join(''):`<div class="empty">${icon('search',32)}<h3>No matching lesson yet</h3><p>Try a shorter term, a technology name, or clear the group filter.</p></div>`}</div>`;}
function topicCard(l){const s=lessonStats(l.id),sk=state.skippedTopics.includes(l.id),q=QUESTIONS.get(l.questionIds[0]);return `<article class="topiccard ${sk?'skipped':''}"><div class="row between"><span class="lessonnum">${n2(l.id)}</span><span class="pill ${sk?'amber':s.done===6?'green':''}">${sk?'Skipped for now':s.done===6?'Quiz attempted':pageRef(l)}</span></div><h3>${esc(l.title)}</h3><p>${esc(q.concept)} &middot; ${esc(QUESTIONS.get(l.questionIds[5]).concept)}<br>${l.definitions.length} definitions &middot; 6 questions &middot; 3 exercises</p><div class="row between small muted" style="margin-bottom:8px"><span>${s.done}/6 attempted</span><span>${s.correct}/6 currently correct</span></div><div class="progressbar"><span style="width:${s.done/6*100}%"></span></div><div class="row"><button class="btn primary sm" data-action="start" data-id="${l.id}">${icon('play',13)}Practice</button><button class="btn sm" data-action="lesson" data-id="${l.id}">Learn first</button><span class="spacer"></span><button class="textbtn" data-action="skip-topic" data-id="${l.id}">${sk?'Restore':'Skip'}</button></div></article>`;}
function openLesson(id,v='lesson'){if(!LESSONS.has(id))return;activeLesson=id;state.lastLesson=id;view=v;activeExercise=null;flashIndex=0;flashBack=false;termIndex=state.definitionReading[id]||0;termBack=false;lessonMode='single';save();render(true);}
function resumePractice(){if(state.session&&state.session.index<state.session.ids.length){view='quiz';activeLesson=questionNow().lesson;render(true);return;}startSession(nextLessonId(state.lastLesson)||state.lastLesson,'guided');}
function startSession(id,mode='guided',customIds=null){if(!LESSONS.has(id))return;activeLesson=id;state.lastLesson=id;state.skippedTopics=state.skippedTopics.filter(x=>x!==id);let ids=customIds?customIds.filter(x=>QUESTIONS.has(x)):LESSONS.get(id).questionIds.filter(q=>mode==='guided'||mode==='review'||QUESTIONS.get(q).level===Number(mode));if(mode==='guided'&&!customIds){const pending=ids.filter(q=>!state.answers[q]&&!state.skipped.includes(q));if(pending.length)ids=pending;else{const notSkipped=ids.filter(q=>!state.skipped.includes(q));if(notSkipped.length)ids=notSkipped;}}
 if(!ids.length){toast('No questions match this practice selection.');return;}state.session={ids,index:0,results:{},mode,selected:null,help:{},lesson:id};view='quiz';save();render(true);}
function quizPage(){const s=state.session;if(!s)return `<div class="empty"><h2>Your next question is ready.</h2><button class="btn primary" data-action="resume">Start practice</button></div>`;const q=questionNow();if(!q)return sessionDone();activeLesson=q.lesson;const l=LESSONS.get(q.lesson),r=s.results[q.id],marked=state.bookmarks.includes(q.id);const done=Object.keys(s.results).length;return `<div class="learntop"><div><div class="eyebrow">LESSON ${n2(l.id)} &middot; ${esc(DATA.groups[l.group-1].title)}</div><h1>${esc(l.title)}</h1><p>One question at a time. Understanding comes before speed.</p></div><button class="btn sm" data-action="nav" data-view="lessons">${icon('list',14)}Topics</button></div><div class="learninglayout"><div><div class="quiztoolbar"><div class="segmented" role="group" aria-label="Practice difficulty">${['guided','1','2','3'].map(m=>`<button class="${s.mode===m?'active':''}" data-action="level" data-level="${m}">${m==='guided'?'Guided path':levelName(Number(m))}</button>`).join('')}</div><span class="spacer"></span><button class="textbtn" data-action="lesson" data-id="${l.id}">${icon('book',13)}Teach me first</button></div><section class="card questioncard" aria-labelledby="questionHeading"><div class="questionmeta"><div class="row wrap">${labelLevel(q.level)}<span class="small muted">Question ${s.index+1} of ${s.ids.length}</span></div><div class="row"><button class="iconbtn" data-action="bookmark" data-id="${q.id}" aria-label="${marked?'Remove bookmark':'Bookmark question'}" aria-pressed="${marked}" style="${marked?'color:var(--accent);background:var(--accent2)':''}">${icon('bookmark',16)}</button><button class="iconbtn" data-action="source" data-id="${l.id}" aria-label="Read source lesson">${icon('book',16)}</button></div></div><div class="progressbar"><span style="width:${s.index/s.ids.length*100}%"></span></div><div class="eyebrow" style="font-size:9px;margin-bottom:10px">${esc(q.concept)}</div><h2 id="questionHeading" tabindex="-1">${esc(q.prompt)}</h2><div class="options" role="radiogroup" aria-label="Choose the best answer">${q.options.map((text,i)=>{let cls=r?(i===q.answer?'correct':i===r.chosen?'incorrect':'dimmed'):s.selected===i?'selected':'';return `<button id="option${i}" role="radio" aria-checked="${r?r.chosen===i:s.selected===i}" class="option ${cls}" data-action="choose" data-option="${i}" ${r?'disabled':''}><span class="letter">${'ABCD'[i]}</span><span class="optiontext">${esc(text)}</span>${r&&i===q.answer?icon('check',17):r&&i===r.chosen?icon('close',17):''}</button>`;}).join('')}</div>${r?`<div class="feedback ${r.correct?'':'wrong'}" role="status"><h3>${icon(r.correct?'check':'bulb',17)}${r.correct?'That is right. Here is why.':'Not quite. Let\'s make the distinction clear.'}</h3>${!r.correct?`<p><b>Best answer: ${'ABCD'[q.answer]}.</b> ${esc(q.options[q.answer])}</p>`:''}<p>${esc(q.explanation)}</p><div class="small">Workbook Lesson ${n2(l.id)}, ${pageRef(l)}. ${s.help?.[q.id]?'You used study help on this question.':''}</div></div>`:''}<div class="quizfooter">${r?`<button class="btn primary" data-action="next">${s.index+1===s.ids.length?'Finish this round':'Next question'}${icon('arrow',16)}</button>`:`<button class="btn primary" data-action="check" ${s.selected===null?'disabled':''}>Check answer ${icon('check',15)}</button>`}<button class="btn" data-action="hint">${icon('bulb',15)}${r?'Explain again':'Need a hint?'}</button><span class="spacer"></span><button class="textbtn" data-action="skip-question" ${r?'disabled':''}>Skip for now ${icon('skip',13)}</button></div></section><div class="shortcuts"><span class="key">1-4</span> choose <span class="key">Enter</span> check / next <span class="spacer"></span><button class="textbtn" style="font-size:10px" data-action="skip-current-topic">Skip this topic</button></div>${definitionHelp(l,q.concept+' '+q.prompt)}${notePanel('q:'+q.id)}<p class="footersource">${done} checked in this round. Question choices are adapted from the workbook, not a certified exam. Skipping never counts as a wrong answer.</p></div><aside id="tutorHost"></aside></div>`;}
function choose(i){const q=questionNow(),s=state.session;if(!q||s.results[q.id]||i<0||i>3)return;s.selected=i;save();render();$('#option'+i)?.focus({preventScroll:true});}
function checkAnswer(){const q=questionNow(),s=state.session;if(!q||s.selected===null||s.results[q.id])return;const chosen=s.selected,correct=chosen===q.answer,prev=state.answers[q.id];s.results[q.id]={chosen,correct};state.answers[q.id]={chosen,correct,firstCorrect:prev?prev.firstCorrect:correct,attempts:(prev?.attempts||0)+1,at:new Date().toISOString(),assisted:!!s.help?.[q.id]};state.skipped=state.skipped.filter(x=>x!==q.id);state.events.push({id:q.id,day:localDay(),correct});if(state.events.length>10000)state.events=state.events.slice(-10000);save();render();}
function nextQuestion(){const s=state.session;if(!s)return;s.index=Math.min(s.ids.length,s.index+1);s.selected=null;save();render(true);$('#questionHeading')?.focus({preventScroll:true});}
function skipQuestion(){const q=questionNow();if(!q||state.session.results[q.id])return;if(!state.skipped.includes(q.id))state.skipped.push(q.id);save();nextQuestion();toast('Skipped without penalty. Find it in Review queue > Skipped questions.');}
function skipTopic(id,advance=false){if(!LESSONS.has(id))return;const was=state.skippedTopics.includes(id);state.skippedTopics=was?state.skippedTopics.filter(x=>x!==id):[...state.skippedTopics,id];save();if(advance&&!was){const next=nextLessonId(id%38+1);if(next)startSession(next);else{view='review';reviewTab='topics';render(true);}}else render();toast(was?'Topic restored to your path.':'Topic skipped for now. You can restore it in All lessons or Review queue.');}
function sessionDone(){const s=state.session,rr=Object.values(s.results),right=rr.filter(r=>r.correct).length,wrongIds=Object.keys(s.results).filter(id=>!s.results[id].correct),skipped=s.ids.filter(id=>!s.results[id]).length;const next=nextLessonId(s.lesson%38+1);return `<div class="pageheading"><div class="eyebrow">Learning is a loop, not a race</div><h1>Round complete.</h1><p>Keep the ideas that clicked. Revisit the ones that need another example.</p></div><div class="card sessiondone"><div class="doneicon">${icon('check',34)}</div><h2>${right} correct out of ${rr.length} checked</h2><p class="muted">${skipped} skipped without penalty. This round is saved in your progress.</p><div class="row wrap">${wrongIds.length?`<button class="btn primary" data-action="retry-round">${icon('refresh',16)}Retry these ${wrongIds.length}</button>`:''}${next?`<button class="btn ${wrongIds.length?'':'primary'}" data-action="start" data-id="${next}">Continue to Lesson ${n2(next)}${icon('arrow',16)}</button>`:''}<button class="btn" data-action="exercises" data-id="${s.lesson}">Try the workbook exercises</button></div><div class="notice" style="max-width:650px;margin:25px auto 0">Before moving on, say one explanation aloud: what the idea means, where you used it, and one limitation. Selecting an answer is practice; explaining it shows deeper understanding.</div></div>`;}
function notePanel(key){return `<details class="card questionnote"><summary>${icon('note',15)} My note for this idea <span class="small muted">Saved locally</span></summary><textarea class="field notearea" data-note-key="${esc(key)}" maxlength="12000" aria-label="Personal note" placeholder="Write the distinction in your own words, or note what you still need to verify...">${esc(state.notes[key]||'')}</textarea></details>`;}
function lessonPage(){const l=LESSONS.get(activeLesson),idx=Math.min(state.definitionReading[l.id]||0,l.definitions.length-1),d=l.definitions[idx],done=l.definitions.filter(x=>state.definitionStatus[x.id]?.rating==='known').length;return `<div class="learntop"><div><div class="eyebrow">LESSON ${n2(l.id)} / 38 &middot; DEFINITIONS EDITION</div><h1>${esc(l.title)}</h1><p>${esc(!l.prerequisites||l.prerequisites==='None'?'No prerequisites. Start here.':'Before this lesson: '+l.prerequisites)}</p></div><button class="btn sm" data-action="nav" data-view="lessons">${icon('list',14)}All lessons</button></div><div class="learninglayout"><div><div class="lessonactions"><button class="btn primary" data-action="start" data-id="${l.id}">${icon('play',15)}Practice questions</button><button class="btn" data-action="termcards" data-id="${l.id}">${icon('layers',15)}Recall definitions</button><button class="btn" data-action="exercises" data-id="${l.id}">${icon('note',15)}Exercises</button></div><div class="definition-navigation"><label for="definitionJump">Jump to any term</label><select id="definitionJump" class="field">${l.definitions.map((x,i)=>`<option value="${x.id}" ${idx===i?'selected':''}>${i+1}. ${esc(x.term)}</option>`).join('')}</select><button class="btn sm" data-action="glossary-lesson" data-id="${l.id}">${icon('list',14)}See all terms</button></div><section class="card learncard definition-main"><div class="row between wrap"><span class="pill accent">ONE TERM. ONE EXAMPLE.</span><span class="small muted">${idx+1} / ${l.definitions.length} &middot; ${esc(definitionStatusLabel(d.id))}</span></div><div class="progressbar" style="margin-top:18px"><span style="width:${(idx+1)/l.definitions.length*100}%"></span></div>${definitionBody(d)}<div class="definition-ratings"><button class="btn sm" data-action="definition-rate" data-id="${d.id}" data-rating="known">${icon('check',14)}I understand</button><button class="btn sm" data-action="definition-rate" data-id="${d.id}" data-rating="again">${icon('refresh',14)}Review again</button><button class="textbtn" data-action="definition-skip" data-id="${d.id}">Skip this term ${icon('skip',13)}</button></div><div class="readingnav"><button class="btn" data-action="definition-prev" ${idx===0?'disabled':''}>${icon('back',15)}Previous term</button>${idx+1<l.definitions.length?`<button class="btn primary" data-action="definition-next">Next term ${icon('arrow',15)}</button>`:`<button class="btn primary" data-action="start" data-id="${l.id}">Try the questions ${icon('play',15)}</button>`}</div><div class="definition-summary small muted">${done} / ${l.definitions.length} terms self-rated as understood. Ratings are separate from quiz scores.</div></section><div class="cue"><b>Try saying it aloud:</b> What is ${esc(d.term)}? Give your own example, then name one limitation.</div><details class="card" style="margin-top:16px"><summary><b>Where this connects to your CV</b></summary><p class="small" style="margin-top:14px;line-height:1.8">${esc(l.cv)}</p><p class="small"><b>Memory cue:</b> ${esc(l.memory||'Define it, trace an example, then explain the choice.')}</p></details>${notePanel('d:'+d.id)}<div class="lessonactions"><button class="textbtn" data-action="source" data-id="${l.id}">Original worked examples & lesson</button><span class="spacer"></span><button class="textbtn" data-action="skip-topic" data-id="${l.id}">${state.skippedTopics.includes(l.id)?'Restore topic':'Skip this topic'}</button></div>${definitionReferences(l)}</div><aside id="tutorHost"></aside></div>`;}
function flashcardsPage(){const l=LESSONS.get(activeLesson),q=QUESTIONS.get(l.questionIds[flashIndex]),rating=state.cards[q.id]?.rating;return `<div class="learntop"><div><div class="eyebrow">LESSON ${n2(l.id)} / RECALL CARDS</div><h1>Say it before you reveal it.</h1><p>${esc(l.title)}</p></div><button class="btn sm" data-action="lesson" data-id="${l.id}">Back to lesson</button></div><div class="learninglayout"><div><div class="row between" style="margin-bottom:15px">${labelLevel(q.level)}<span class="small muted">Card ${flashIndex+1} of 6 ${rating?' / '+(rating==='known'?'Marked understood':'Needs another pass'):''}</span></div><section class="card flashcard"><div class="eyebrow">${esc(q.concept)}</div><h2>${esc(flashBack?q.options[q.answer]:q.prompt)}</h2>${flashBack?`<p>${esc(q.explanation)}</p><button class="textbtn" data-action="pdf" data-page="${l.page}">Workbook Lesson ${n2(l.id)}, ${pageRef(l)}</button>`:`<p class="muted">Try explaining this without the four answer choices. Then reveal the answer and compare your reasoning.</p>`}<button class="btn primary" data-action="flip-card">${icon('refresh',15)}${flashBack?'See the question':'Reveal the answer'}</button></section>${flashBack?`<div class="flashrating"><button class="btn" data-action="rate-card" data-rating="again">${icon('refresh',14)}Need another pass</button><button class="btn primary" data-action="rate-card" data-rating="known">${icon('check',14)}I can explain this</button></div>`:''}<div class="readingnav"><button class="btn" data-action="card-prev" ${flashIndex===0?'disabled':''}>${icon('back',14)}Previous</button><button class="btn" data-action="card-next" ${flashIndex===5?'disabled':''}>Next${icon('arrow',14)}</button></div><p class="footersource">Self-ratings go to the review queue. They do not change your multiple-choice scores.</p>${definitionHelp(l,q.concept+' '+q.prompt)}${notePanel('q:'+q.id)}</div><aside id="tutorHost"></aside></div>`;}
function exercisesPage(){const l=LESSONS.get(activeLesson);if(!activeExercise)activeExercise=l.exercises[0].id;return `<div class="learntop"><div><div class="eyebrow">LESSON ${n2(l.id)} / ORIGINAL WORKBOOK EXERCISES</div><h1>Put it into your own words.</h1><p>Three original exercises. Write, compare with the answer key, and self-assess.</p></div><button class="btn sm" data-action="lesson" data-id="${l.id}">Back to lesson</button></div><div class="learninglayout"><div>${l.exercises.map(e=>{const r=state.exercises[e.id]||{};return `<section class="card exerciseitem" id="exercise-${e.id.replace('.','-')}"><div class="row between wrap"><span class="pill ${activeExercise===e.id?'accent':''}">${esc(e.id)}</span><button class="textbtn" data-action="discuss-exercise" data-id="${e.id}">${icon('chat',14)}Discuss this exercise</button></div><h3 style="margin-top:14px">${esc(e.question)}</h3><label class="small muted" for="answer-${e.id}">Your answer (saved locally)</label><textarea id="answer-${e.id}" class="field notearea" data-exercise-id="${e.id}" maxlength="12000" rows="4" placeholder="Try it without looking at the answer...">${esc(r.text||'')}</textarea><div class="row wrap" style="margin-top:12px"><button class="btn sm" data-action="reveal-exercise" data-id="${e.id}">${icon('bulb',14)}${r.revealed?'Hide answer key':'Compare with answer key'}</button>${r.rating?`<span class="small muted">${r.rating==='known'?'Self-rated: understood':'Self-rated: revisit'}</span>`:''}</div>${r.revealed?`<div class="exerciseanswer"><b>Workbook answer</b><p style="white-space:pre-wrap;margin-top:8px">${esc(e.answer)}</p><div class="row wrap"><button class="btn sm" data-action="rate-exercise" data-id="${e.id}" data-rating="again">Need more practice</button><button class="btn sm" data-action="rate-exercise" data-id="${e.id}" data-rating="known">I understand the reasoning</button></div></div>`:''}</section>`;}).join('')}${definitionHelp(l,l.title)}<p class="footersource">No automatic grading is claimed for written answers. Compare your reasoning, not just the wording. ${pageRef(l)} of your original workbook.</p></div><aside id="tutorHost"></aside></div>`;}
function reviewIds(){if(reviewTab==='mistakes')return DATA.questions.filter(q=>state.answers[q.id]&&!state.answers[q.id].correct).map(q=>q.id);if(reviewTab==='skipped')return [...state.skipped];if(reviewTab==='bookmarks')return [...state.bookmarks];if(reviewTab==='cards')return DATA.questions.filter(q=>state.cards[q.id]?.rating==='again').map(q=>q.id);return [];}
function reviewPage(){const ids=reviewIds(),labels={mistakes:'Mistakes',skipped:'Skipped questions',bookmarks:'Bookmarks',cards:'Question recall',definitions:'Definitions',topics:'Skipped topics',exercises:'Written exercises'};return `<div class="pageheading"><div class="eyebrow">Second attempts are part of learning</div><h1>Your review queue.</h1><p>Return to what needs attention. Skipped items never reduce your score.</p></div><div class="filtertabs">${Object.entries(labels).map(([key,label])=>`<button class="filtertab ${reviewTab===key?'active':''}" data-action="review-tab" data-tab="${key}">${label}</button>`).join('')}</div>${reviewTab==='definitions'?definitionReview():ids.length?`<div class="row between wrap" style="margin-bottom:16px"><p class="small muted">${ids.length} question${ids.length===1?'':'s'} in this queue</p><button class="btn primary" data-action="practice-review">${icon('play',14)}Practice this queue</button></div><div class="reviewlist">${ids.map(id=>{const q=QUESTIONS.get(id),l=LESSONS.get(q.lesson);return `<div class="reviewitem"><span class="lessonnum">${n2(l.id)}</span><div class="body"><h3>${esc(q.prompt)}</h3><p>${levelName(q.level)} / ${esc(q.concept)}</p></div><button class="btn sm" data-action="practice-one" data-id="${id}">Practice</button>${['skipped','bookmarks'].includes(reviewTab)?`<button class="iconbtn" data-action="remove-review" data-id="${id}" aria-label="Remove from ${esc(labels[reviewTab])}">${icon('close',15)}</button>`:''}</div>`;}).join('')}</div>`:reviewTab==='topics'&&state.skippedTopics.length?`<div class="reviewlist">${state.skippedTopics.map(id=>`<div class="reviewitem"><span class="lessonnum">${n2(id)}</span><div class="body"><h3>${esc(LESSONS.get(id).title)}</h3><p>Skipped topic. Your previous progress is preserved.</p></div><button class="btn sm" data-action="skip-topic" data-id="${id}">Restore</button><button class="btn primary sm" data-action="start" data-id="${id}">Practice</button></div>`).join('')}</div>`:reviewTab==='exercises'&&Object.entries(state.exercises).some(([,v])=>v.rating==='again')?`<div class="reviewlist">${Object.entries(state.exercises).filter(([,v])=>v.rating==='again').map(([id])=>{const e=EXERCISES.get(id);return `<div class="reviewitem"><div class="body"><h3>${esc(id)} / ${esc(e.question)}</h3><p>Your self-assessment: revisit this exercise.</p></div><button class="btn sm" data-action="goto-context" data-key="e:${id}">Revisit</button></div>`;}).join('')}</div>`:`<div class="empty">${icon('check',35)}<h3>No items in this queue.</h3><p>${reviewTab==='mistakes'?'Questions last answered incorrectly will appear here. Try a lesson to begin.':'Your saved items will appear here as you study.'}</p><button class="btn primary" data-action="resume">Go to practice</button></div>`}`;}
function coveragePage(){const query=coverageSearch.toLowerCase().trim(),rows=DATA.coverage.filter(c=>!query||c.label.toLowerCase().includes(query));return `<div class="pageheading row between wrap"><div><div class="eyebrow">Nothing gets lost in the small print</div><h1>Your complete CV map.</h1><p>153 source checklist entries. Each takes you to the corresponding lesson.</p></div><span class="pill accent">${state.coverage.length} / 153 self-checked</span></div><div class="notice" style="margin-bottom:18px">Check an entry when you can explain it in your own words. This is your self-assessment, separate from quiz performance. Some entries contain several related skills.</div><label class="searchbox" style="margin-bottom:20px">${icon('search',17)}<input id="coverageSearch" aria-label="Search CV coverage" placeholder="Find Kysely, RAG, TableOS, TOTP..." value="${esc(coverageSearch)}"></label><div class="card" style="padding:8px 14px">${rows.length?rows.map(c=>`<div class="coverageitem"><input type="checkbox" data-coverage-id="${c.id}" aria-label="I can explain: ${esc(c.label)}" ${state.coverage.includes(c.id)?'checked':''}><div class="body"><span>${esc(c.label)}</span></div><div class="row">${c.lessons.map(id=>`<button class="btn sm" data-action="lesson" data-id="${id}" title="${esc(LESSONS.get(id).title)}">Lesson ${n2(id)}</button>`).join('')}</div></div>`).join(''):'<p class="muted small" style="padding:20px">No exact match. Try a shorter skill name.</p>'}</div><p class="footersource">Checklist transcribed from workbook pages 82-90. Source references are available in the embedded original PDF.</p>`;}
function planPage(){return `<div class="pageheading"><div class="eyebrow">A route, not a deadline</div><h1>Your three-day focus.</h1><p>Follow the workbook's route without racing past the foundations. All days stay open.</p></div>${DATA.plan.map(d=>`<div class="planrow"><div class="daytile">DAY<strong>${d.day}</strong></div><section class="card"><h2>${esc(d.title)}</h2><p class="muted">${esc(d.focus)}</p><div class="row wrap"><button class="btn primary sm" data-action="start" data-id="${d.lessons[0]}">Start day ${d.day}${icon('arrow',14)}</button><button class="textbtn" data-action="lesson" data-id="${d.lessons[0]}">Read the first idea</button></div><div class="lessonchips">${d.lessons.map(id=>`<button data-action="lesson" data-id="${id}" title="${esc(LESSONS.get(id).title)}">${n2(id)} ${esc(LESSONS.get(id).title.split(':')[0])}</button>`).join('')}</div></section></div>`).join('')}<section class="card textwide"><h2>The answer structure to practise aloud</h2><p><b>Problem</b> &rarr; <b>basic mechanism</b> &rarr; <b>choice</b> &rarr; <b>trade-off</b> &rarr; <b>evidence.</b></p><p class="muted small">Name the user need. Explain what the component does. Compare an alternative. State a limitation. Finish with what you personally implemented or measured. Do not invent missing deployment, research or benchmark details.</p><button class="textbtn" data-action="pdf" data-page="3">Read the original three-day route ${icon('external',13)}</button></section>`;}
function contextTitle(key){if(key.startsWith('d:')){const d=DEFINITIONS.get(key.slice(2));return d?`Lesson ${n2(d.lesson)} / ${d.term}`:key;}if(key.startsWith('q:')){const q=QUESTIONS.get(key.slice(2));return q?`Lesson ${n2(q.lesson)} / ${q.concept}`:key;}if(key.startsWith('e:'))return key.slice(2)+' / Workbook exercise';const l=LESSONS.get(Number(key.slice(2)));return l?`Lesson ${n2(l.id)} / ${l.title}`:key;}
function notesPage(){const notes=Object.entries(state.notes).filter(([,text])=>text.trim()),threads=Object.entries(state.threads).filter(([,m])=>m.length);return `<div class="pageheading"><div class="eyebrow">Your own explanations matter</div><h1>Notes & saved discussions.</h1><p>Local to this browser. Export a backup before moving devices or clearing browser data.</p></div><div class="row between" style="margin-bottom:18px"><h2>${notes.length} personal notes</h2><button class="btn sm" data-action="export">${icon('download',14)}Export progress</button></div>${notes.length?notes.map(([key,text])=>`<article class="card noteitem"><div class="row between"><h3>${esc(contextTitle(key))}</h3><button class="textbtn" data-action="goto-context" data-key="${esc(key)}">Open ${icon('arrow',13)}</button></div><p>${esc(text)}</p></article>`).join(''):`<div class="empty"><h3>A place for your own words.</h3><p>Open "My note" below any quiz question or lesson card to save what clicked.</p></div>`}<h2 style="margin:28px 0 16px">${threads.length} question discussions</h2><div class="reviewlist">${threads.map(([key,msgs])=>`<div class="reviewitem"><span class="lessonnum">${icon('chat',16)}</span><div class="body"><h3>${esc(contextTitle(key))}</h3><p>${msgs.length} saved messages / ${esc((msgs.filter(m=>m.role==='user').at(-1)?.text||'Discussion').slice(0,110))}</p></div><button class="btn sm" data-action="goto-context" data-key="${esc(key)}">Reopen</button></div>`).join('')||'<p class="small muted">Your tutor discussions will appear here. They stay attached to their original question or exercise.</p>'}</div>`;}
function settingsPage(){return `<div class="pageheading"><div class="eyebrow">You are in control</div><h1>Setup & backups.</h1><p>Core learning works without an account, API key, installation, or internet connection.</p></div><div class="settingsgrid"><section class="card"><h2>${icon('target',18)} Daily practice goal</h2><p>A gentle target, not a lock. Repeat attempts count toward daily activity.</p><label for="dailyGoal" class="small">Questions per day</label><input id="dailyGoal" class="field" type="number" min="1" max="100" value="${state.settings.goal}" style="max-width:130px;margin-top:9px"></section><section class="card"><h2>${icon('shield',18)} Your progress stays here</h2><p>Answers, bookmarks, notes and discussions are saved in this browser's local storage. There is no account, cloud sync or invisible analytics. Browser privacy settings can block saving.</p><div class="row wrap"><button class="btn sm" data-action="export">${icon('download',14)}Export backup</button><button class="btn sm" data-action="import">${icon('upload',14)}Import backup</button></div><input id="progressFile" class="fileinput" type="file" accept="application/json,.json"><p style="margin-top:12px">Before replacing or moving the HTML file, export a backup from your old portal and import it here. Old backups remain compatible. File mode, different filenames and local-server mode may have separate storage.</p></section><section class="card full"><div class="row between wrap"><h2>${icon('chat',18)} Two honest tutor modes</h2><span class="pill ${backend.available?'green':''}">${backend.available?'AI configuration detected':'Workbook helper ready'}</span></div><p><b>Workbook helper (always available):</b> prepared explanations plus separate term definitions, concrete examples and clarification notes. It is a local, deterministic lookup tool, not a live AI model. Unmatched questions are acknowledged rather than invented.</p><p><b>Live AI tutor (optional):</b> natural follow-up conversation grounded in the lesson. This needs the included local server, an OpenAI API key, a Responses-compatible model, and an internet connection. API usage may incur charges separate from a ChatGPT subscription.</p>${backend.available?`<div class="notice accent">Configured model: <b>${esc(backend.model)}</b>. Configuration is detected; this is not a guarantee of API credit or model access.</div><div class="row wrap" style="margin-top:12px"><button class="btn primary sm" data-action="enable-ai">Enable live tutor</button><button class="btn sm" data-action="disable-ai">Use workbook helper</button></div>`:`<ol><li>Extract the complete portal ZIP into a folder.</li><li>Install Python 3 if it is not already installed. Copy <code>.env.example</code> to <code>.env</code>.</li><li>Set <code>OPENAI_API_KEY</code> and <code>OPENAI_MODEL</code> in that local file. Use a model available in your own API account.</li><li>Run <code>python server.py</code> (or <code>Start-Portal.bat</code> on Windows). Open the local address printed in the terminal.</li><li>Choose <b>Live AI</b> in the tutor panel and approve sending the relevant context.</li></ol>`}<p>The API key stays in the local server; never paste it into a question, note or browser field. With live AI enabled, your message, current workbook context, and recent discussion are sent to OpenAI. No AI requests run until you send a message. Responses may be wrong; check the source.</p><button class="btn sm" data-action="check-backend">${icon('refresh',14)}Check server connection</button></section><section class="card"><h2>${icon('book',18)} Source & scope</h2><p>${esc(DATA.book.note)}</p><p>38 lessons, 228 adapted MCQs, 114 original exercises, ${DEFLIST.length} expanded definition/example entries, and 153 source checklist entries. The 434 original source passages and embedded PDF are preserved separately. Mathematics/code layout in extracted text may differ from the original PDF.</p><button class="btn sm" data-action="pdf" data-page="1">${icon('external',14)}Open original workbook</button></section><section class="card"><h2>${icon('settings',18)} Keyboard & reset</h2><p>During a quiz: <b>1-4</b> selects an answer. <b>Enter</b> checks it, then advances after feedback. These shortcuts are disabled while typing a comment or note. <b>Escape</b> closes a dialog.</p><p>Reset only affects this portal's saved learning data. Export before resetting.</p><button class="btn sm" data-action="reset" style="color:var(--red)">${icon('trash',14)}Reset learning progress</button></section></div>`;}
function renderTutor(){const host=$('#tutorHost');if(!host)return;const c=context(),msgs=state.threads[c.key]||[],isAI=state.settings.tutorMode==='ai'&&backend.available&&state.settings.aiConsent;host.innerHTML=`<section class="tutor" aria-label="Question discussion and tutor"><div class="chathead"><div class="row between"><h2>${icon('spark',17)}Learning companion</h2><span class="pill ${isAI?'green':''}" style="font-size:9px">${isAI?'LIVE AI':'WORKBOOK'}</span></div><p>Ask without losing your place.</p><div class="tutorcontext">${esc(c.title)}</div><label class="sr-only" for="tutorMode">Tutor mode</label><select id="tutorMode" class="field" style="font-size:11px;margin-top:10px;padding:6px"><option value="offline" ${!isAI?'selected':''}>Definitions helper / no API needed</option><option value="ai" ${isAI?'selected':''}>Live AI / optional server connection</option></select></div><div id="chatMessages" class="chatmessages" aria-live="polite" aria-relevant="additions">${msgs.length?msgs.map(m=>`<div class="chatbubble ${m.role==='user'?'user':'assistant'}"><div class="chatlabel">${m.role==='user'?'YOU':esc(m.label||'Workbook helper')}</div><div style="white-space:pre-wrap;overflow-wrap:anywhere">${formatChatText(m.text)}</div>${m.sources?.length?`<div class="row wrap" style="margin-top:9px">${m.sources.map(s=>`<button class="textbtn" data-action="pdf" data-page="${s.page}">Lesson ${n2(s.lesson)}, p.${s.page}</button>`).join('')}</div>`:''}</div>`).join(''):`<div class="chatempty">${icon('chat',29)}<h3>${c.definition?'A word still unclear?':'A question about the question?'}</h3><p>${isAI?'Your live tutor will use the current lesson and discussion. Ask for simpler words, another example, or a comparison.':'Ask for the explanation, find a definition, or look up an example. Definitions appear one term at a time with an example. This is prepared lookup, not a live model; open-ended conversation requires the optional live tutor.'}</p></div>`}${busy.has(c.key)?'<div class="chatbusy"><span class="spin"></span>Waiting for the live tutor...</div>':''}</div><div class="chatquick"><button data-action="tutor-prompt" data-prompt="Explain this">Explain this</button><button data-action="tutor-prompt" data-prompt="Show an example">Show an example</button><button data-action="tutor-prompt" data-prompt="${c.definition?'Common confusion':'Why not the other options?'}">${c.definition?'Common confusion':'Why not the others?'}</button><button data-action="copy-context" title="Copy context to ask in ChatGPT">${icon('copy',10)}Ask in ChatGPT</button></div><form id="tutorForm" class="chatcomposer"><label class="sr-only" for="tutorInput">Ask a follow-up question</label><textarea id="tutorInput" maxlength="4000" placeholder="${c.definition?'Define a word, ask for an example...':'What does this mean? Why not option B?'}" ${busy.has(c.key)?'disabled':''}></textarea><div class="row"><small>${isAI?'Uses your API account; costs may apply.':'Prepared definitions, not live AI.'}</small><span class="spacer"></span><button type="submit" class="btn primary" ${busy.has(c.key)?'disabled':''}>Send ${icon('arrow',13)}</button></div></form></section>`;const area=$('#chatMessages');area.scrollTop=area.scrollHeight;}
function sourceMatches(text,c,examples=false){const stop=new Set('what why how does do is are a an the this that it of for and to in me my you can could please explain tell about with from would should i not other options answer give show example simpler'.split(' '));const terms=[...new Set(text.toLowerCase().match(/[a-z0-9]+/g)||[])].filter(t=>t.length>1&&!stop.has(t));const candidates=[];for(const l of DATA.lessons){for(const p of l.reading){const low=(p.heading+' '+p.text).toLowerCase();const hits=terms.reduce((n,t)=>n+(new RegExp('\\b'+t+'\\b','i').test(low)?1:0),0);let score=hits*8+(l.id===c.lesson?2:0);if(examples&&l.id===c.lesson&&/example|trace|follow|worked/i.test(p.heading))score+=20;if(!terms.length&&!examples&&l.id===c.lesson)score+=1;if(hits>0||(examples&&score>=20))candidates.push({text:p.text,heading:p.heading,page:p.page,lesson:l.id,score,hits});}}return candidates.sort((a,b)=>b.score-a.score).slice(0,3);}
function offlineReply(text,c){const q=c.question,l=LESSONS.get(c.lesson),simple=text.trim().toLowerCase();const explain=/^(explain this|explain again|give me a simpler explanation|simplify|help|i don'?t understand|what does this mean)[?.!]*$/i.test(simple),why=/why not|other options|other answers|option [abcd1-4]/i.test(simple),example=/^(show|give|give me)?\s*(an? |another )?(example|analogy)[?.!]*$/i.test(simple);if(c.definition&&(explain||example||simple==='define this'||simple==='common confusion'||simple==='what should i remember?'))return {text:termText(c.definition)+'\n\nTry it: Explain the term in your own words and give a second example. This is a prepared teaching entry, not a newly generated AI response.',label:'Expanded definition / teaching example',sources:[{lesson:l.id,page:l.page}]};if(q&&(explain||why)){let result=`Best answer: ${'ABCD'[q.answer]}. ${q.options[q.answer]}\n\nWhy: ${q.explanation}`;if(why){const match=simple.match(/option\s*([abcd1-4])/i);if(match){let idx='abcd'.indexOf(match[1]);if(idx<0)idx=Number(match[1])-1;result=`Option ${'ABCD'[idx]}: ${q.options[idx]}\n\n${idx===q.answer?'That is the best answer.':'Compare this claim with the supported answer.'}\n\n`+result;}}const ds=relatedDefinitionIds(l,q.concept+' '+q.prompt,2).map(id=>DEFINITIONS.get(id));if(ds.length)result+='\n\nTerms behind this answer:\n\n'+ds.map(termText).join('\n\n');return {text:result,label:'Prepared explanation & definitions',sources:[{lesson:l.id,page:l.page}]};}if(c.exercise&&explain)return {text:`Workbook answer: ${c.exercise.answer}\n\n`+relatedDefinitionIds(l,c.exercise.question,2).map(id=>termText(DEFINITIONS.get(id))).join('\n\n')+'\n\nThe written exercise is self-assessed, not automatically graded.',label:'Original answer / expanded definitions',sources:[{lesson:l.id,page:l.page}]};let matches=definitionMatches(text,c.lesson,3);if(!matches.length&&example)matches=c.definition?[c.definition]:relatedDefinitionIds(l,q?.concept||c.exercise?.question||l.title,2).map(id=>DEFINITIONS.get(id));if(matches.length)return {text:matches.map(termText).join('\n\n')+'\n\nThese are prepared teaching entries. For an open-ended explanation of your particular situation, use Live AI or Ask in ChatGPT.',label:'Definitions lookup / no live AI',sources:matches.map(d=>({lesson:d.lesson,page:d.page}))};return {text:'No matching definition was found for that wording. Try a specific term, such as backend, embedding or idempotency.\n\nThis offline helper searches prepared entries and answers; it cannot invent a new explanation. Use Live AI or Ask in ChatGPT for a natural follow-up. Your comment is saved here.',label:'Definitions helper / no match',sources:[]};}
async function sendTutor(text){text=String(text||'').trim().slice(0,4000);if(!text)return;const c=context();if(busy.has(c.key))return;if(view==='quiz'&&state.session){state.session.help[c.question.id]=true;}const arr=state.threads[c.key]||(state.threads[c.key]=[]);arr.push({role:'user',text,at:new Date().toISOString()});if(arr.length>38)arr.splice(0,arr.length-38);const isAI=state.settings.tutorMode==='ai'&&backend.available&&state.settings.aiConsent;save();renderTutor();if(!isAI){const reply=offlineReply(text,c);arr.push({role:'assistant',...reply,at:new Date().toISOString()});save();if(context().key===c.key)renderTutor();return;}busy.add(c.key);renderTutor();try{const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),65000);let response;try{response=await fetch('/api/tutor',{method:'POST',headers:{'Content-Type':'application/json','X-Portal-Token':backend.token},body:JSON.stringify({lesson:c.lesson,questionId:c.question?.id||null,exerciseId:c.exercise?.id||null,definitionId:c.definition?.id||null,message:text,learnerChoice:c.question?(state.answers[c.question.id]?.chosen??null):null,writtenAnswer:c.exercise?(state.exercises[c.exercise.id]?.text||'').slice(0,4000):null,history:arr.slice(-7,-1).map(m=>({role:m.role,text:m.text.slice(0,4000)}))}),signal:controller.signal});}finally{clearTimeout(timer);}const out=await response.json();if(!response.ok)throw Error(out.error||'The local tutor request did not complete.');arr.push({role:'assistant',text:String(out.answer||'The model returned no readable text.'),label:'Live AI / check against source',sources:[{lesson:c.lesson,page:LESSONS.get(c.lesson).page}],at:new Date().toISOString()});}catch(e){arr.push({role:'assistant',text:`The live tutor could not answer: ${e.name==='AbortError'?'The request timed out.':e.message}\n\nNo answer has been invented. Workbook explanations remain available by switching modes.`,label:'Connection error',sources:[],at:new Date().toISOString()});}finally{busy.delete(c.key);save();if($('#tutorHost')&&context().key===c.key)renderTutor();}}
async function fetchHealth(silent=true){if(!/^https?:$/.test(location.protocol)){backend={available:false,token:null,model:null};if(!silent)toast('Open the portal through the included local Python server to enable Live AI.');return;}try{const ctrl=new AbortController(),timer=setTimeout(()=>ctrl.abort(),4000);let r;try{r=await fetch('/api/health',{cache:'no-store',signal:ctrl.signal});}finally{clearTimeout(timer);}if(!r.ok)throw Error('Server endpoint unavailable');const b=await r.json();backend={available:b.aiAvailable===true,token:typeof b.csrfToken==='string'?b.csrfToken:null,model:String(b.model||'')};if(!silent)toast(backend.available?'Local server detected. AI credentials are configured, but have not yet been validated by a request.':'Local server is running. Set your API key and model in .env, then restart it.');}catch(e){backend={available:false,token:null,model:null};if(!silent)toast('Optional tutor server not detected. Offline learning is still fully available.');}renderNav();if(view==='settings')render();else if($('#tutorHost'))renderTutor();}
function showModal(title,body,footer=''){lastFocus=document.activeElement;$('#modalRoot').innerHTML=`<div class="modalbackdrop" data-action="backdrop"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modalTitle"><header class="modalheader"><h2 id="modalTitle">${esc(title)}</h2><button class="iconbtn" data-action="close-modal" aria-label="Close dialog">${icon('close',18)}</button></header><div class="modalbody">${body}</div>${footer?`<footer class="modalfooter">${footer}</footer>`:''}</section></div>`;document.body.style.overflow='hidden';$('.shell').inert=true;$('#sidebar').inert=true;$('#modalRoot button')?.focus();}
function closeModal(){if(!$('#modalRoot').firstChild)return;$('#modalRoot').innerHTML='';document.body.style.overflow='';$('.shell').inert=false;$('#sidebar').inert=false;if(lastFocus?.isConnected)lastFocus.focus({preventScroll:true});}
function sourceModal(id){const l=LESSONS.get(id);if(!l)return;showModal(`Lesson ${n2(id)} / Source workbook`, `<p class="notice">Original extracted lesson text, including the exercises and answer key. Use the PDF when code or formula formatting matters.</p><h2>${esc(l.title)}</h2>${l.source.map(p=>`<div class="sourceblock"><button class="textbtn" data-action="pdf" data-page="${p.page}">Original page ${p.page}${icon('external',12)}</button>${p.code?`<pre class="codeblock">${esc(p.text)}</pre>`:`<p>${esc(p.text)}</p>`}</div>`).join('')}`,`<button class="btn" data-action="close-modal">Back to practice</button><button class="btn primary" data-action="pdf" data-page="${l.page}">Open original PDF</button>`);}
function openPDF(page=1){if(!pdfURL){const encoded=$('#pdf-data').textContent.trim(),binary=atob(encoded),bytes=new Uint8Array(binary.length);for(let i=0;i<binary.length;i++)bytes[i]=binary.charCodeAt(i);pdfURL=URL.createObjectURL(new Blob([bytes],{type:'application/pdf'}));}const w=window.open(pdfURL+'#page='+Math.max(1,Math.min(96,Number(page)||1)),'_blank');if(w)w.opener=null;else{const a=document.createElement('a');a.href=pdfURL;a.download=DATA.book.filename;a.click();toast('Your browser blocked the new tab. The original workbook has been downloaded instead.');}}
function help(){showModal('One term at a time',`<p><b>Learn first:</b> Every lesson now opens with separate <b>Term: definition</b>, <b>Example:</b> and <b>Remember:</b> entries. Jump to any term, skip it, or mark it for review.</p><p><b>Definitions & examples:</b> Search all ${DEFLIST.length} entries, filter by lesson, and open a term for discussion.</p><p><b>Recall:</b> Explain a term and give your own example before revealing the prepared answer. Self-ratings do not affect quiz accuracy.</p><p><b>Practice:</b> The original 228 questions, 114 exercises and 153 CV-map entries remain. Quizzes also have an expandable definitions section.</p><p><b>Ask:</b> The offline companion retrieves prepared definition/example entries. Live AI requires the included local server and your credentials; Ask in ChatGPT copies context for you to paste here.</p><p><b>Upgrade safely:</b> Export your backup from the old portal and import it through Setup & backups. Moving or renaming HTML files can change browser storage. The original PDF is preserved, not rewritten.</p>`);}
function requestAI(){if(!backend.available){showModal('Enable the optional live tutor',`<p>Your portal already supports offline quizzes, prepared explanations and workbook search. For real open-ended AI conversation, use the local server included in the complete ZIP.</p><p>Configure <code>OPENAI_API_KEY</code> and <code>OPENAI_MODEL</code> in a local <code>.env</code> file, then run <code>python server.py</code>. Never put the key in the browser.</p><p>This is not automatically connected to this ChatGPT conversation. You can also use "Ask in ChatGPT" to copy a question with its source context.</p>`,`<button class="btn" data-action="close-modal">Keep offline mode</button><button class="btn primary" data-action="setup-from-modal">Setup instructions</button>`);renderTutor();return;}showModal('Use your API account for live replies?',`<p>When you press Send, the local server will send your message, the current lesson, the question or exercise, your selected or written answer, and a short recent discussion to OpenAI. Relevant source passages may be included.</p><p><b>No question is sent until you ask.</b> The API key remains on the local server. API usage charges and provider data policies apply. Do not enter secrets or confidential company information.</p><p>Configured model: <b>${esc(backend.model)}</b>. Generated explanations can be wrong; consult the source when uncertain.</p>`,`<button class="btn" data-action="close-modal">Cancel</button><button class="btn primary" data-action="confirm-ai">Enable live AI</button>`);}
function buildCopyContext(){const c=context(),l=LESSONS.get(c.lesson),last=(state.threads[c.key]||[]).filter(m=>m.role==='user').at(-1);return `Please tutor me using separate entries in this exact style:\nTerm: A plain-language definition.\nExample: A concrete, clearly labelled teaching example.\nRemember: One common confusion or limitation.\n\nNever combine several terms into a definition paragraph. Define abbreviations before using them. Build from basics before trade-offs. Distinguish supplied CV facts from teaching expansions; do not invent deployment details or research results.\n\nLesson ${n2(l.id)}: ${l.title}\nSource: ${DATA.book.title}, ${pageRef(l)}.\n\n${c.definition?'CURRENT TERM:\n'+termText(c.definition):c.question?'QUESTION: '+c.question.prompt+'\n'+c.question.options.map((x,i)=>'ABCD'[i]+'. '+x).join('\n')+'\nPrepared explanation: '+c.question.explanation:c.exercise?'EXERCISE: '+c.exercise.question+'\nSOURCE ANSWER: '+c.exercise.answer:'LESSON: '+l.title}\n\nMY QUESTION: ${$('#tutorInput')?.value.trim()||last?.text||'Explain this step by step, with an example, and check my understanding.'}\n\nEXPANDED TEACHING ENTRIES (not quotations or extra CV claims):\n${(c.definition?[c.definition]:relatedDefinitionIds(l,c.question?.concept||c.exercise?.question||l.title,3).map(id=>DEFINITIONS.get(id))).map(termText).join('\n\n')}\n\nORIGINAL WORKBOOK EXCERPTS:\n${l.reading.slice(0,12).map(p=>`[p.${p.page}] ${p.text}`).join('\n\n')}`;}
async function copyContext(){const text=buildCopyContext();try{await navigator.clipboard.writeText(text);toast('Context copied. Paste it into this ChatGPT conversation and add your follow-up.');}catch(e){showModal('Copy your question into ChatGPT',`<p>Select and copy the text below, then paste it into your ChatGPT conversation. Nothing is sent automatically.</p><textarea class="field" id="copyText" rows="14" readonly>${esc(text)}</textarea>`,`<button class="btn primary" data-action="close-modal">Done</button>`);$('#copyText').focus();$('#copyText').select();}}
function exportProgress(){const payload={...state,exportedAt:new Date().toISOString(),portalVersion:DATA.version};const url=URL.createObjectURL(new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=`Arslan_Learning_Progress_${localDay()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);toast('Backup exported. Keep it somewhere safe; it contains your notes and discussions.');}
let pendingImport=null;
async function importProgress(file){if(!file)return;try{if(file.size>8*1024*1024)throw Error('Progress files must be smaller than 8 MB.');pendingImport=validateState(JSON.parse(await file.text()));showModal('Replace current progress with this backup?',`<p>The backup contains <b>${Object.keys(pendingImport.answers).length} attempted questions</b>, ${Object.keys(pendingImport.notes).length} note entries and ${Object.keys(pendingImport.threads).length} discussions.</p><p>This replaces rather than merges the current browser's progress. Export a backup first to keep both.</p>`,`<button class="btn" data-action="close-modal">Cancel</button><button class="btn" data-action="export">Export current</button><button class="btn primary" data-action="confirm-import">Import backup</button>`);}catch(e){pendingImport=null;toast('Import rejected: '+e.message+' Your existing progress is unchanged.');}}
function gotoContext(key){closeModal();if(key.startsWith('d:')){openDefinition(key.slice(2));}else if(key.startsWith('q:')){const q=QUESTIONS.get(key.slice(2));if(q)startSession(q.lesson,'review',[q.id]);}else if(key.startsWith('e:')){const e=EXERCISES.get(key.slice(2));if(e){openLesson(e.lesson,'exercises');activeExercise=e.id;render();$('#exercise-'+e.id.replace('.','-'))?.scrollIntoView({block:'start'});}}else if(key.startsWith('l:'))openLesson(Number(key.slice(2)));}
let searchTimer;
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el||el.disabled)return;const action=el.dataset.action,id=Number(el.dataset.id);switch(action){
case 'nav':navigate(el.dataset.view);break;
case 'resume':resumePractice();break;
case 'start':startSession(id);break;
case 'definition-open':openDefinition(el.dataset.id);break;
case 'definition-recall':openDefinition(el.dataset.id,true);break;
case 'termcards':openLesson(id,'termcards');break;
case 'definition-rate':rateDefinition(el.dataset.id,el.dataset.rating);render();break;
case 'definition-skip':{rateDefinition(el.dataset.id,'skipped');const l=LESSONS.get(activeLesson);state.definitionReading[l.id]=Math.min(l.definitions.length-1,(state.definitionReading[l.id]||0)+1);save();render();break;}
case 'definition-prev':case 'definition-next':{const l=LESSONS.get(activeLesson);state.definitionReading[l.id]=Math.max(0,Math.min(l.definitions.length-1,(state.definitionReading[l.id]||0)+(action==='definition-next'?1:-1)));save();render();break;}
case 'glossary-lesson':glossaryLesson=String(id);glossarySearch='';glossaryStatus='all';glossaryPageIndex=0;view='glossary';render(true);break;
case 'glossary-clear':glossaryLesson='all';glossarySearch='';glossaryStatus='all';glossaryPageIndex=0;render();break;
case 'glossary-prev':case 'glossary-next':glossaryPageIndex+=action==='glossary-next'?1:-1;render(true);break;
case 'term-flip':termBack=!termBack;render();break;
case 'term-prev':case 'term-next':{const l=LESSONS.get(activeLesson);termIndex=Math.max(0,Math.min(l.definitions.length-1,termIndex+(action==='term-next'?1:-1)));termBack=false;state.definitionReading[l.id]=termIndex;save();render();break;}
case 'term-skip':case 'term-rate':{rateDefinition(el.dataset.id,action==='term-skip'?'skipped':el.dataset.rating);const l=LESSONS.get(activeLesson);if(termIndex<l.definitions.length-1){termIndex++;termBack=false;}state.definitionReading[l.id]=termIndex;save();render();break;}
case 'lesson':openLesson(id);break;
case 'flashcards':openLesson(id,'flashcards');break;
case 'exercises':openLesson(id,'exercises');break;
case 'level':startSession(activeLesson,el.dataset.level);break;
case 'choose':choose(Number(el.dataset.option));break;
case 'check':checkAnswer();break;
case 'next':nextQuestion();break;
case 'skip-question':skipQuestion();break;
case 'skip-topic':skipTopic(id);break;
case 'skip-current-topic':skipTopic(activeLesson,true);break;
case 'bookmark':{const qid=el.dataset.id;state.bookmarks=state.bookmarks.includes(qid)?state.bookmarks.filter(x=>x!==qid):[...state.bookmarks,qid];save();render();break;}
case 'hint':{const q=questionNow();if(!q)break;state.session.help[q.id]=true;save();const checked=state.session.results[q.id];if(checked)sendTutor('Explain this');else showModal('A small nudge',`<p>${esc(q.hint)}</p><p>Ask yourself which option keeps responsibilities separate. You can also read the source card or ask for the complete explanation; using help is recorded, not penalized.</p>`,`<button class="btn" data-action="close-modal">Try answering</button><button class="btn primary" data-action="hint-explain">Show explanation in tutor</button>`);break;}
case 'hint-explain':closeModal();sendTutor('Explain this');break;
case 'retry-round':{const ids=Object.keys(state.session.results).filter(x=>!state.session.results[x].correct);if(ids.length)startSession(QUESTIONS.get(ids[0]).lesson,'review',ids);break;}
case 'reading-prev':case 'reading-next':{const l=LESSONS.get(activeLesson);state.reading[l.id]=Math.max(0,Math.min(l.reading.length-1,(state.reading[l.id]||0)+(action==='reading-next'?1:-1)));save();render();break;}
case 'flip-card':flashBack=!flashBack;render();break;
case 'card-prev':case 'card-next':flashIndex=Math.max(0,Math.min(5,flashIndex+(action==='card-next'?1:-1)));flashBack=false;render();break;
case 'rate-card':{const q=context().question;state.cards[q.id]={rating:el.dataset.rating,at:new Date().toISOString()};save();toast(el.dataset.rating==='known'?'Marked understood. Your quiz score is unchanged.':'Saved to Review queue > Recall cards.');if(flashIndex<5){flashIndex++;flashBack=false;}render();break;}
case 'reveal-exercise':{const eid=el.dataset.id,r=state.exercises[eid]||(state.exercises[eid]={text:'',rating:null,revealed:false});r.revealed=!r.revealed;activeExercise=eid;save();render();break;}
case 'rate-exercise':{const eid=el.dataset.id,r=state.exercises[eid]||(state.exercises[eid]={text:'',revealed:true});r.rating=el.dataset.rating;activeExercise=eid;save();render();toast('Self-assessment saved. Quiz scores are unchanged.');break;}
case 'discuss-exercise':activeExercise=el.dataset.id;renderTutor();$('#tutorInput')?.focus({preventScroll:window.innerWidth>1040});toast('The tutor is now focused on '+activeExercise+'.');break;
case 'review-tab':reviewTab=el.dataset.tab;render();break;
case 'practice-review':{const ids=reviewIds();if(ids.length)startSession(QUESTIONS.get(ids[0]).lesson,'review',ids);break;}
case 'practice-one':{const q=QUESTIONS.get(el.dataset.id);startSession(q.lesson,'review',[q.id]);break;}
case 'remove-review':{const key=reviewTab==='skipped'?'skipped':'bookmarks';state[key]=state[key].filter(x=>x!==el.dataset.id);save();render();break;}
case 'goto-context':gotoContext(el.dataset.key);break;
case 'tutor-prompt':sendTutor(el.dataset.prompt);break;
case 'copy-context':copyContext();break;
case 'source':sourceModal(id);break;
case 'pdf':openPDF(el.dataset.page);break;
case 'help':help();break;
case 'close-modal':closeModal();break;
case 'backdrop':if(e.target===el)closeModal();break;
case 'toggle-menu':$('#sidebar').classList.toggle('open');$('#menuOverlay').classList.toggle('visible');break;
case 'export':exportProgress();break;
case 'import':$('#progressFile').click();break;
case 'confirm-import':if(pendingImport){state=pendingImport;pendingImport=null;activeLesson=state.lastLesson;state.settings.tutorMode='offline';state.settings.aiConsent=false;save();closeModal();view='dashboard';render(true);toast('Backup restored. Live AI remains off until you enable it.');}break;
case 'reset':showModal('Reset this browser\'s learning progress?',`<p>This clears all answers, bookmarks, notes and tutor discussions saved by this portal. It does not change the original workbook.</p><p>Export a backup first to keep a copy.</p>`,`<button class="btn" data-action="close-modal">Cancel</button><button class="btn" data-action="export">Export first</button><button class="btn primary" data-action="confirm-reset">Reset everything</button>`);break;
case 'confirm-reset':state=defaultState();activeLesson=1;save();closeModal();view='dashboard';render(true);toast('Learning progress reset.');break;
case 'enable-ai':requestAI();break;
case 'confirm-ai':state.settings.tutorMode='ai';state.settings.aiConsent=true;save();closeModal();render();toast('Live AI enabled. Requests begin only when you send a message.');break;
case 'disable-ai':state.settings.tutorMode='offline';save();render();break;
case 'setup-from-modal':closeModal();navigate('settings');break;
case 'check-backend':fetchHealth(false);break;
}});
document.addEventListener('input',e=>{const t=e.target;if(t.dataset.noteKey){state.notes[t.dataset.noteKey]=t.value.slice(0,12000);save();}else if(t.dataset.exerciseId){const id=t.dataset.exerciseId;state.exercises[id]={...(state.exercises[id]||{revealed:false,rating:null}),text:t.value.slice(0,12000)};save();}else if(t.id==='lessonSearch'||t.id==='coverageSearch'||t.id==='glossarySearch'){const pos=t.selectionStart,key=t.id,value=t.value;clearTimeout(searchTimer);searchTimer=setTimeout(()=>{if(key==='lessonSearch')lessonSearch=value;else if(key==='glossarySearch'){glossarySearch=value;glossaryPageIndex=0;}else coverageSearch=value;render();const el=$('#'+key);if(el){el.focus();el.setSelectionRange(pos,pos);}},140);}});
document.addEventListener('change',e=>{const t=e.target;if(t.id==='definitionJump'){openDefinition(t.value);}else if(t.id==='glossaryLesson'){glossaryLesson=t.value;glossaryPageIndex=0;render();}else if(t.id==='glossaryStatus'){glossaryStatus=t.value;glossaryPageIndex=0;render();}else if(t.id==='lessonGroup'){lessonGroup=t.value;render();}else if(t.dataset.coverageId){const id=Number(t.dataset.coverageId);state.coverage=t.checked?[...new Set([...state.coverage,id])]:state.coverage.filter(x=>x!==id);save();render();}else if(t.id==='dailyGoal'){state.settings.goal=Math.max(1,Math.min(100,parseInt(t.value,10)||10));save();t.value=state.settings.goal;toast('Daily target saved.');}else if(t.id==='tutorMode'){if(t.value==='ai')requestAI();else{state.settings.tutorMode='offline';save();renderTutor();renderNav();}}else if(t.id==='progressFile'){importProgress(t.files[0]);t.value='';}});
document.addEventListener('submit',e=>{if(e.target.id==='tutorForm'){e.preventDefault();sendTutor($('#tutorInput').value);}});
document.addEventListener('keydown',e=>{const modal=$('#modalRoot .modal');if(modal){if(e.key==='Escape'){closeModal();e.preventDefault();}else if(e.key==='Tab'){const nodes=[...modal.querySelectorAll('button,input,select,textarea,a[href],[tabindex="0"]')].filter(x=>!x.disabled);if(nodes.length){const first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){last.focus();e.preventDefault();}else if(!e.shiftKey&&document.activeElement===last){first.focus();e.preventDefault();}}}return;}if(e.target.matches('input,textarea,select,[contenteditable="true"]'))return;if(['lesson','termcards'].includes(view)&&!e.target.matches('button,a')){if(e.key==='ArrowRight'||e.key==='ArrowLeft'){const l=LESSONS.get(activeLesson),delta=e.key==='ArrowRight'?1:-1;if(view==='lesson'){state.definitionReading[l.id]=Math.max(0,Math.min(l.definitions.length-1,(state.definitionReading[l.id]||0)+delta));save();}else{termIndex=Math.max(0,Math.min(l.definitions.length-1,termIndex+delta));termBack=false;}render();e.preventDefault();return;}if(view==='termcards'&&e.key===' '){termBack=!termBack;render();e.preventDefault();return;}}if(view==='quiz'&&questionNow()){if(/^[1-4]$/.test(e.key)){choose(Number(e.key)-1);e.preventDefault();}else if(e.key==='Enter'&&(!e.target.matches('button')||e.target.classList.contains('option'))){if(state.session.results[questionNow().id])nextQuestion();else checkAnswer();e.preventDefault();}}});

function definitionNow(){const l=LESSONS.get(activeLesson);if(!l)return null;const i=view==='termcards'?termIndex:(state.definitionReading[l.id]||0);return l.definitions[Math.max(0,Math.min(l.definitions.length-1,i))];}
function termText(d){return `${d.term}: ${d.definition}\nExample: ${d.example}\nRemember: ${d.note}`;}
function definitionBody(d,compact=false){return `<div class="definition-body ${compact?'compact':''}"><p class="term-definition"><strong>${esc(d.term)}:</strong> ${esc(d.definition)}</p><div class="definition-example"><strong>Example:</strong> ${esc(d.example)}</div><div class="definition-remember"><strong>Remember:</strong> ${esc(d.note)}</div></div>`;}
function definitionStatusLabel(id){const s=state.definitionStatus[id]?.rating;return s==='known'?'I can explain it':s==='again'?'Review again':s==='skipped'?'Skipped for now':'Not self-rated';}
function definitionReferences(l){return `<details class="definition-provenance"><summary>Source & teaching notes</summary><p>Expanded teaching definitions follow Lesson ${n2(l.id)}. Examples are illustrations unless explicitly labelled as CV-reported facts. Page links identify the original lesson, not an exact quotation of the expanded wording.</p><button class="textbtn" data-action="source" data-id="${l.id}">Original lesson passages</button> &middot; <button class="textbtn" data-action="pdf" data-page="${l.page}">Original workbook ${pageRef(l)}</button>${l.definitionReferences?.length?`<div class="reference-links">${l.definitionReferences.map(r=>`<a href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">${esc(r.label)}</a>`).join('')}</div>`:''}</details>`;}
function openDefinition(id,recall=false){const d=DEFINITIONS.get(id);if(!d)return;activeLesson=d.lesson;state.lastLesson=d.lesson;const l=LESSONS.get(d.lesson);const idx=l.definitions.findIndex(x=>x.id===id);state.definitionReading[d.lesson]=idx;termIndex=idx;termBack=false;lessonMode='single';view=recall?'termcards':'lesson';save();render(true);}
function rateDefinition(id,rating){if(!DEFINITIONS.has(id)||!['known','again','skipped'].includes(rating))return;state.definitionStatus[id]={rating,at:new Date().toISOString()};save();toast(rating==='known'?'Understanding marked. Quiz scores are unchanged.':rating==='skipped'?'Skipped without penalty. Find it in Review queue > Definitions.':'Saved in Review queue > Definitions.');}
function definitionMatches(text,lessonId=activeLesson,limit=4){const norm=s=>String(s||'').toLowerCase().replace(/[^a-z0-9+#]+/g,' ').trim();const input=norm(text);const stop=new Set('a an the what is are does do mean meaning define explain this that me give show example of for in to and or why how please with from simpler simple tell about can you i dont understand difference between versus vs'.split(' '));const qt=new Set(input.split(' ').filter(t=>!stop.has(t)&&t.length>1));if(!qt.size)return [];return DEFLIST.map(d=>{let score=0;for(const alias of d.aliases||[d.term]){const a=norm(alias);if(!a)continue;if(input===a)score=Math.max(score,1000);else if((' '+input+' ').includes(' '+a+' '))score=Math.max(score,150+a.split(' ').length*8);}const tt=new Set(norm(d.term).split(' ').filter(t=>!stop.has(t)));const overlap=[...qt].filter(t=>tt.has(t)).length;if(overlap)score+=overlap*15/Math.max(1,Math.sqrt(qt.size));if(score===0){const words=new Set(norm(d.definition+' '+d.example).split(' '));const hits=[...qt].filter(t=>words.has(t)).length;if(hits===qt.size&&hits>0)score=hits*2;}if(score>0&&d.lesson===lessonId)score+=3;return {d,score};}).filter(x=>x.score>0).sort((a,b)=>b.score-a.score||a.d.lesson-b.d.lesson).filter((x,i,arr)=>arr.findIndex(y=>norm(y.d.term)===norm(x.d.term))===i).slice(0,limit).map(x=>x.d);}
function relatedDefinitionIds(l,text,max=4){const ranked=definitionMatches(text,l.id,20).filter(d=>d.lesson===l.id);const list=ranked.length?ranked:l.definitions.slice(0,max);return list.slice(0,max).map(d=>d.id);}
function definitionHelp(l,text){const ids=relatedDefinitionIds(l,text,4);return `<details class="card definition-help"><summary>${icon('book',16)} Definitions & examples for this topic <span class="small muted">Optional study help</span></summary><div class="definition-help-items">${ids.map(id=>{const d=DEFINITIONS.get(id);return `<article class="definition-mini">${definitionBody(d,true)}<button class="textbtn" data-action="definition-open" data-id="${d.id}">Study this term</button></article>`;}).join('')}</div><button class="btn sm" data-action="glossary-lesson" data-id="${l.id}">All ${l.definitions.length} definitions in Lesson ${n2(l.id)}</button></details>`;}
function glossaryPage(){const query=glossarySearch.trim();let ds=DEFLIST.filter(d=>glossaryLesson==='all'||d.lesson===Number(glossaryLesson));if(query){const words=query.toLowerCase().split(/\s+/).filter(Boolean);ds=ds.filter(d=>words.every(w=>(d.term+' '+d.definition+' '+d.example+' '+d.note).toLowerCase().includes(w)));}if(glossaryStatus!=='all')ds=ds.filter(d=>glossaryStatus==='unrated'?!state.definitionStatus[d.id]:state.definitionStatus[d.id]?.rating===glossaryStatus);const size=18,total=Math.max(1,Math.ceil(ds.length/size));glossaryPageIndex=Math.min(Math.max(0,glossaryPageIndex),total-1);const shown=ds.slice(glossaryPageIndex*size,(glossaryPageIndex+1)*size);return `<div class="pageheading"><div class="eyebrow">LOOK UP A TERM, NOT A PARAGRAPH</div><h1>Definitions & examples.</h1><p>${DEFLIST.length} separate entries across your 38 lessons. Every entry has a definition, a concrete example and a point to remember.</p></div><div class="notice accent glossary-intro">Start in lesson order, or search a term such as <b>software</b>, <b>embedding</b> or <b>idempotency</b>. These are expanded teaching entries; your original workbook and CV evidence remain available separately.</div><div class="definition-filters"><div class="searchbox">${icon('search',16)}<label class="sr-only" for="glossarySearch">Search definitions</label><input id="glossarySearch" value="${esc(glossarySearch)}" placeholder="Search a term, meaning or example..."></div><label class="sr-only" for="glossaryLesson">Filter by lesson</label><select id="glossaryLesson" class="field"><option value="all">All 38 lessons</option>${DATA.lessons.map(l=>`<option value="${l.id}" ${String(l.id)===glossaryLesson?'selected':''}>${n2(l.id)}. ${esc(l.title)}</option>`).join('')}</select><label class="sr-only" for="glossaryStatus">Filter by understanding</label><select id="glossaryStatus" class="field">${[['all','All ratings'],['unrated','Not rated yet'],['known','I understand'],['again','Review again'],['skipped','Skipped']].map(([k,v])=>`<option value="${k}" ${glossaryStatus===k?'selected':''}>${v}</option>`).join('')}</select></div><div class="sectionhead"><p class="small muted">${ds.length} matching ${ds.length===1?'entry':'entries'}${ds.length?` &middot; Showing ${glossaryPageIndex*size+1}-${Math.min((glossaryPageIndex+1)*size,ds.length)}`:''}</p><button class="textbtn" data-action="glossary-clear">Clear filters</button></div><div class="definition-grid">${shown.map(d=>`<article class="card definition-catalog"><div class="row between wrap"><span class="pill">Lesson ${n2(d.lesson)}</span><span class="small muted">${esc(definitionStatusLabel(d.id))}</span></div>${definitionBody(d,true)}<div class="row wrap"><button class="btn sm" data-action="definition-open" data-id="${d.id}">Study & discuss ${icon('arrow',13)}</button><button class="textbtn" data-action="definition-recall" data-id="${d.id}">Test my recall</button></div></article>`).join('')}</div>${!ds.length?'<div class="empty"><h3>No matching definitions.</h3><p>Try a shorter term or clear your lesson and rating filters.</p></div>':''}<div class="readingnav"><button class="btn" data-action="glossary-prev" ${glossaryPageIndex===0?'disabled':''}>${icon('back',14)}Previous entries</button><span class="small muted">Page ${glossaryPageIndex+1} of ${total}</span><button class="btn primary" data-action="glossary-next" ${glossaryPageIndex+1>=total?'disabled':''}>Next entries ${icon('arrow',14)}</button></div><p class="footersource">Learning adaptations and illustrative examples, not additional claims about your implementations. The Study button connects each term to its original lesson and source notes.</p>`;}
function termcardsPage(){const l=LESSONS.get(activeLesson);termIndex=Math.min(Math.max(0,termIndex),l.definitions.length-1);const d=l.definitions[termIndex];return `<div class="learntop"><div><div class="eyebrow">LESSON ${n2(l.id)} / DEFINITION RECALL</div><h1>Define it. Then give an example.</h1><p>${esc(l.title)}</p></div><button class="btn sm" data-action="lesson" data-id="${l.id}">Back to lesson</button></div><div class="learninglayout"><div><div class="row between" style="margin-bottom:16px"><span class="pill accent">Term ${termIndex+1} / ${l.definitions.length}</span><span class="small muted">${esc(definitionStatusLabel(d.id))}</span></div><section class="card term-recall"><div class="eyebrow">${termBack?'COMPARE YOUR EXPLANATION':'ANSWER WITHOUT LOOKING'}</div>${termBack?definitionBody(d):`<h2>${esc(d.term)}</h2><p class="muted">What does it mean? Give a small example and explain one thing it should not be confused with.</p><div class="recall-template"><b>${esc(d.term)}:</b> Explain in your own words.<br><b>Example:</b> Describe one concrete situation.</div>`}<button class="btn primary" data-action="term-flip">${icon('refresh',15)}${termBack?'Hide definition':'Reveal definition & example'}</button></section>${termBack?`<div class="flashrating"><button class="btn" data-action="term-rate" data-id="${d.id}" data-rating="again">${icon('refresh',14)}Need another pass</button><button class="btn primary" data-action="term-rate" data-id="${d.id}" data-rating="known">${icon('check',14)}I can explain it</button></div>`:''}<div class="readingnav"><button class="btn" data-action="term-prev" ${termIndex===0?'disabled':''}>${icon('back',14)}Previous term</button><button class="textbtn" data-action="term-skip" data-id="${d.id}">Skip for now</button><button class="btn" data-action="term-next" ${termIndex+1===l.definitions.length?'disabled':''}>Next term ${icon('arrow',14)}</button></div>${notePanel('d:'+d.id)}<div class="lessonactions"><button class="textbtn" data-action="flashcards" data-id="${l.id}">Original question recall cards</button></div>${definitionReferences(l)}</div><aside id="tutorHost"></aside></div>`;}
function definitionReview(){const ds=DEFLIST.filter(d=>['again','skipped'].includes(state.definitionStatus[d.id]?.rating));return `<div class="definition-review"><div class="notice" style="margin-bottom:16px">Terms marked <b>Review again</b> or <b>Skipped</b> appear here. Understanding ratings are separate from multiple-choice accuracy.</div>${ds.length?`<div class="reviewlist">${ds.map(d=>`<div class="reviewitem"><span class="lessonnum">${n2(d.lesson)}</span><div class="body"><h3>${esc(d.term)}</h3><p>${esc(definitionStatusLabel(d.id))}</p></div><button class="btn sm" data-action="definition-open" data-id="${d.id}">Learn</button><button class="btn primary sm" data-action="definition-recall" data-id="${d.id}">Recall</button></div>`).join('')}</div>`:`<div class="empty"><h3>No definitions waiting for review.</h3><p>Use Review again or Skip on any term to keep it here.</p><button class="btn primary" data-action="nav" data-view="glossary">Browse definitions</button></div>`}</div>`;}
function formatChatText(text){return String(text||'').split('\n').map(line=>{const clean=line.replace(/^\*\*([^*]+):\*\*\s*/, '$1: ').replace(/^\*\*([^*]+)\*\*:\s*/,'$1: ');const match=clean.match(/^([^:]{1,100}):\s+(.*)$/);return match?`<strong>${esc(match[1])}:</strong> ${esc(match[2])}`:esc(clean);}).join('\n');}
render();fetchHealth(true);
})();
